let BASE_URL=location.origin+"/",goToTop=e=>window.scrollTo(0,0),secondsElement=(document.querySelector("head base").href=BASE_URL,document.getElementById("date").innerHTML=`&copy; ${(new Date).getFullYear()} - Code free for fun`,document.querySelector(".seconds")),minutesElement=document.querySelector(".minutes"),hoursElement=document.querySelector(".hours"),timeElement=document.querySelector(".time"),setRotation=(element,rotation)=>element.style.transform=`rotate(${rotation}deg)`,updateWatch=()=>{var now=new Date,seconds=now.getSeconds(),minutes=now.getMinutes(),now=now.getHours(),secondsRotation=6*seconds,seconds=6*minutes+.1*seconds,hoursRotation=30*now+.5*minutes,secondsRotation=(setRotation(secondsElement,secondsRotation),setRotation(minutesElement,seconds),setRotation(hoursElement,hoursRotation),String(now).padStart(2,"0")),seconds=String(minutes).padStart(2,"0");timeElement.textContent=secondsRotation+":"+seconds};setInterval(updateWatch,1e3),updateWatch();